import type { NodeRegistry } from "@spiky-panda/core";
import { createLeakCo2Node, LeakCo2Node } from "./leak-co2.node.js";

/** The type, named under Generated. so that every catalogue says it is generated. */
export const LEAK_CO2_TYPE = "Generated.Physics:leak-co2";

/** The entry the forge calls: register every type of the plugin on the registry. */
export function register(registry: NodeRegistry, doc: (file: string) => string): void {
    const instance = createLeakCo2Node();
    registry.register(
        LEAK_CO2_TYPE,
        () => createLeakCo2Node(),
        {
            label: "CO2 Leak",
            category: "Physics.Habitat",
            docPath: doc("leak-co2.md"),
            inputPorts: instance.inputPorts,
            outputPorts: instance.outputPorts,
            signature: {
                purpose: "A CO2 leak or controlled vent: mass flow out of the habitat scaled by a command (0 to 1), with an editable maximum rate at full opening",
                inputs: {
                    command: {
                        quantity: "Dimensionless",
                        unit: "ratio",
                        description: "Control signal from 0 (closed) to 1 (fully open); defaults to 0 when unwired"
                    }
                },
                outputs: {
                    co2Delta: {
                        quantity: "MassFlow",
                        unit: "kg/s",
                        description: "CO2 mass flow out of the atmosphere (negative: leaves the system)"
                    },
                    lastLeakRate: {
                        quantity: "MassFlow",
                        unit: "kg/s",
                        description: "The CO2 leak rate on the last tick"
                    }
                },
                capabilities: []
            }
        }
    );
}

import {
    RuntimeNode,
    InputPort,
    OutputPort,
    editable,
    viewable
} from "@spiky-panda/core";

/**
 * A CO2 leak or controlled vent: outputs a negative mass flow (CO2 leaving)
 * scaled by a command signal (0 to 1) and an editable maximum rate.
 */
export class LeakCo2Node extends RuntimeNode {
    private _maxRateKgPerS: number = 0.001; // kg/s at full opening
    private _lastLeakRate: number = 0; // kg/s on last tick

    readonly inputPorts = [
        new InputPort("command", "Dimensionless", "ratio")
    ];

    readonly outputPorts = [
        new OutputPort("co2Delta", "MassFlow", "kg/s"),
        new OutputPort("lastLeakRate", "MassFlow", "kg/s")
    ];

    @editable()
    get maxRateKgPerS(): number {
        return this._maxRateKgPerS;
    }

    set maxRateKgPerS(value: number) {
        this._maxRateKgPerS = Math.max(0, value);
    }

    @viewable()
    get lastLeakRate(): number {
        return this._lastLeakRate;
    }

    fire(session: any, t: number): void {
        // Read command input (0 to 1), default to 0 if unwired
        const command = session.readSignal(this, "command") ?? 0;
        const clampedCommand = Math.max(0, Math.min(1, command));

        // Calculate leak rate: negative because CO2 leaves the system
        this._lastLeakRate = -clampedCommand * this._maxRateKgPerS;

        // Publish outputs
        session.writeSignal(this, "co2Delta", this._lastLeakRate);
        session.writeSignal(this, "lastLeakRate", this._lastLeakRate);
    }
}

/** Factory function to create a new LeakCo2Node instance. */
export function createLeakCo2Node(): LeakCo2Node {
    return new LeakCo2Node();
}

import { test } from "node:test";
import { strict as assert } from "node:assert";
import { createLeakCo2Node } from "./leak-co2.node.js";

test("LeakCo2Node: basic instantiation", () => {
    const node = createLeakCo2Node();
    assert.ok(node, "Node should be created");
    assert.equal(node.maxRateKgPerS, 0.001, "Default max rate should be 0.001 kg/s");
    assert.equal(node.lastLeakRate, 0, "Initial leak rate should be 0");
});

test("LeakCo2Node: input and output ports", () => {
    const node = createLeakCo2Node();
    assert.equal(node.inputPorts.length, 1, "Should have 1 input port");
    assert.equal(node.inputPorts[0].name, "command", "Input port should be named 'command'");
    assert.equal(node.outputPorts.length, 2, "Should have 2 output ports");
    assert.equal(node.outputPorts[0].name, "co2Delta", "First output should be 'co2Delta'");
    assert.equal(node.outputPorts[1].name, "lastLeakRate", "Second output should be 'lastLeakRate'");
});

test("LeakCo2Node: editable maxRateKgPerS", () => {
    const node = createLeakCo2Node();
    node.maxRateKgPerS = 0.005;
    assert.equal(node.maxRateKgPerS, 0.005, "Should set max rate to 0.005 kg/s");
    node.maxRateKgPerS = -0.001;
    assert.equal(node.maxRateKgPerS, 0, "Should clamp negative values to 0");
});

test("LeakCo2Node: fire with command 0 (closed)", () => {
    const node = createLeakCo2Node();
    node.maxRateKgPerS = 0.002;
    const session = {
        readSignal: () => 0,
        writeSignal: () => {}
    };
    node.fire(session, 0);
    assert.equal(node.lastLeakRate, 0, "Leak rate should be 0 when command is 0");
});

test("LeakCo2Node: fire with command 1 (fully open)", () => {
    const node = createLeakCo2Node();
    node.maxRateKgPerS = 0.002;
    const session = {
        readSignal: () => 1,
        writeSignal: () => {}
    };
    node.fire(session, 0);
    assert.equal(node.lastLeakRate, -0.002, "Leak rate should be -maxRate when command is 1");
});

test("LeakCo2Node: fire with command 0.5 (half open)", () => {
    const node = createLeakCo2Node();
    node.maxRateKgPerS = 0.004;
    const session = {
        readSignal: () => 0.5,
        writeSignal: () => {}
    };
    node.fire(session, 0);
    assert.equal(node.lastLeakRate, -0.002, "Leak rate should be -0.5 * maxRate when command is 0.5");
});

test("LeakCo2Node: fire with unwired command (defaults to 0)", () => {
    const node = createLeakCo2Node();
    node.maxRateKgPerS = 0.003;
    const session = {
        readSignal: () => undefined,
        writeSignal: () => {}
    };
    node.fire(session, 0);
    assert.equal(node.lastLeakRate, 0, "Leak rate should be 0 when command is unwired");
});

test("LeakCo2Node: fire clamps command to [0, 1]", () => {
    const node = createLeakCo2Node();
    node.maxRateKgPerS = 0.001;
    const session = {
        readSignal: () => 1.5,
        writeSignal: () => {}
    };
    node.fire(session, 0);
    assert.equal(node.lastLeakRate, -0.001, "Leak rate should be clamped to -maxRate when command > 1");
});

