    const node = new GainNode();
    reg.register(GAIN_TYPE, () => createGainNode(), {
        label: "Gain",
        category: "Generated.Example",
        docPath: doc("gain.md"),
        inputPorts: [...node.inputPorts],
        outputPorts: [...node.outputPorts],
